class Solution:
    def minDiffInBST(self, root: 'TreeNode | None') -> int:
        best = float('inf')
        prev = None                       # previous value in sorted (in-order) order

        def inorder(node):
            nonlocal best, prev
            if not node:
                return
            inorder(node.left)
            if prev is not None:
                best = min(best, node.val - prev)   # sorted order: only neighbours matter
            prev = node.val
            inorder(node.right)

        inorder(root)                     # visits each node once; recursion depth = tree height
        return best
